@page "/apply"
@rendermode InteractiveServer
@using sv_6ad0eebb6d53477485b85b1f9a47a7cc.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var stepIndex = i;
        var css = stepIndex == _currentStep ? "step active"
                : stepIndex < _currentStep ? "step completed"
                : "step future";
        <div class="@css" @onclick="() => GoToStep(stepIndex)">
            <span class="step-number">
                @if (stepIndex < _currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@_stepNames[stepIndex]</span>
        </div>
        @if (stepIndex < _stepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger mt-3">@_errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (_currentStep)
    {
        case 0:
            @RenderPersonalInfo();
            break;
        case 1:
            @RenderWorkHistory();
            break;
        case 2:
            @RenderReferences();
            break;
        case 3:
            @RenderCoverLetter();
            break;
        case 4:
            @RenderReview();
            break;
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() => @<div>
    <h3>Personal Information</h3>
    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" @bind="_fullName" />
    </div>
    <div class="mb-3">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" @bind="_email" />
    </div>
    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" @bind="_phone" />
    </div>
    <div class="mb-3">
        <label class="form-label">Address *</label>
        <textarea class="form-control" @bind="_address"></textarea>
    </div>
    <div class="d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
            @if (_isValidating) { <span>Validating...</span> } else { <span>Next</span> }
        </button>
    </div>
</div>;}

@* Step 2: Work History *@
@{ RenderFragment RenderWorkHistory() => @<div>
    <h3>Work History</h3>
    @for (int i = 0; i < _workEntries.Count; i++)
    {
        var idx = i;
        <div class="card mb-3 p-3">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h5>Position @(idx + 1)</h5>
                @if (_workEntries.Count > 1)
                {
                    <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                }
            </div>
            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Company *</label>
                    <input type="text" class="form-control" value="@_workEntries[idx].Company"
                           @onchange="(e) => UpdateWork(idx, w => w.Company = e.Value?.ToString() ?? string.Empty)" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" value="@_workEntries[idx].Title"
                           @onchange="(e) => UpdateWork(idx, w => w.Title = e.Value?.ToString() ?? string.Empty)" />
                </div>
            </div>
            <div class="row mb-2">
                <div class="col-md-4">
                    <label class="form-label">Start Date *</label>
                    <input type="date" class="form-control" value="@_workEntries[idx].StartDate?.ToString("yyyy-MM-dd")"
                           @onchange="(e) => UpdateWork(idx, w => w.StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" value="@_workEntries[idx].EndDate?.ToString("yyyy-MM-dd")"
                           disabled="@_workEntries[idx].IsCurrent"
                           @onchange="(e) => UpdateWork(idx, w => w.EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check">
                        <input type="checkbox" class="form-check-input" id="current-@idx" checked="@_workEntries[idx].IsCurrent"
